    $statusLabels = ['menunggu_pembayaran' => 'Menunggu pembayaran', 'menunggu_verifikasi' => 'Menunggu verifikasi', 'menunggu_konfirmasi' => 'Menunggu konfirmasi', 'dikonfirmasi' => 'Siap dikerjakan', 'dikerjakan' => $awaitingSellerRevision ? 'Menunggu revisi' : 'Sedang dikerjakan', 'menunggu_persetujuan' => 'Menunggu persetujuan', 'selesai' => 'Pesanan selesai', 'dibatalkan' => 'Pesanan dibatalkan'];
    $statusLabel = $statusLabels[$order->status] ?? ucfirst(str_replace('_', ' ', $order->status));
    $addonTotal = (float) $order->addons->sum('price');
    $total = (float) ($order->final_price ?? $order->estimated_price ?? 0);
    $basePrice = max(0, $total - $addonTotal);
    $bookingFields = collect(data_get($order->service?->booking_config, 'fields', []))->keyBy('name');
    $buyerNote = $order->messages->where('sender_id', $order->buyer_id)->last();
    $orderInformation = collect($order->booking_data ?? []);
    $formatRank = fn ($rank, $division, $stars) => trim($rank . ($division ? ' ' . $division : '') . ($stars !== null ? ' · ' . $stars . ' bintang' : ''));
    if ($order->jokiMlOrder) {
        $joki = $order->jokiMlOrder;
        $orderInformation = collect([
            'current_rank' => $formatRank($joki->current_rank, $joki->current_division, $joki->current_stars),
            'target_rank' => $formatRank($joki->target_rank, $joki->target_division, $joki->target_stars),
            'total_stars_needed' => $joki->total_stars_needed ? $joki->total_stars_needed . ' bintang' : null,
            'ml_username' => $joki->ml_username,
            'ml_password' => $joki->ml_password_encrypted ? 'Tersimpan aman' : null,
            'hero_notes' => $joki->hero_notes,
            'additional_notes' => $joki->additional_notes,
        ])->filter();
    } elseif ($order->barberOrder) {
        $barber = $order->barberOrder;
        $orderInformation = $orderInformation->merge([
            'haircut_type' => $barber->selected_haircut_type,
            'additional_services' => $barber->selected_additional_services,
            'special_requests' => $barber->special_requests,
        ])->filter();
    }
    $fieldLabels = [
        'current_rank' => 'Rank awal', 'target_rank' => 'Rank tujuan', 'total_stars_needed' => 'Total bintang',
        'ml_username' => 'Username / ID Mobile Legends', 'ml_password' => 'Password akun',
        'hero_notes' => 'Catatan hero', 'additional_notes' => 'Catatan tambahan',
        'haircut_type' => 'Jenis potongan', 'additional_services' => 'Layanan tambahan', 'special_requests' => 'Permintaan khusus',
    ];
