<script>
function cancelOrder(orderId, button) { if (!confirm('Apakah Anda yakin ingin membatalkan pesanan ini?')) return; button.disabled = true; button.textContent = 'Memproses...'; fetch(`/pesanan/${orderId}/cancel`, {method:'POST', headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content || ''}}).then(response => response.ok ? window.location.reload() : Promise.reject()).catch(() => { button.disabled = false; button.textContent = 'Batalkan pesanan'; }); }
</script>
